CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('customer','admin') NOT NULL DEFAULT 'customer', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS api_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS products (id VARCHAR(80) PRIMARY KEY, slug VARCHAR(190) NOT NULL UNIQUE, title VARCHAR(255) NOT NULL, description TEXT, category VARCHAR(80) NOT NULL, image_url TEXT, price_paise BIGINT NOT NULL, active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS product_variants (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id VARCHAR(80) NOT NULL, size VARCHAR(30) NOT NULL, color VARCHAR(100) NOT NULL, gsm VARCHAR(100) NOT NULL DEFAULT '', price_paise BIGINT NOT NULL, stock INT UNSIGNED NOT NULL DEFAULT 0, UNIQUE KEY unique_variant(product_id,size,color,gsm), FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, public_id CHAR(32) NOT NULL UNIQUE, customer_name VARCHAR(150) NOT NULL, email VARCHAR(190) NOT NULL, phone VARCHAR(20) NOT NULL, shipping_address JSON NOT NULL, subtotal_paise BIGINT NOT NULL, shipping_paise BIGINT NOT NULL, total_paise BIGINT NOT NULL, status ENUM('pending_payment','paid','processing','shipped','delivered','cancelled','refunded') NOT NULL DEFAULT 'pending_payment', razorpay_order_id VARCHAR(120) UNIQUE NULL, razorpay_payment_id VARCHAR(120) UNIQUE NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, product_id VARCHAR(80) NULL, title VARCHAR(255) NOT NULL, size VARCHAR(30) NOT NULL, color VARCHAR(100) NOT NULL, gsm VARCHAR(100) NOT NULL DEFAULT '', quantity INT UNSIGNED NOT NULL, unit_price_paise BIGINT NOT NULL, custom_design JSON NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payment_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_id VARCHAR(150) NOT NULL UNIQUE, event_type VARCHAR(100) NOT NULL, received_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
